interface InflightHandoff {
  /** 一次性 listener 的 detach 函数，abort/完成时调 */
  detachListener: () => void
  /** 600s 超时 timer，abort/完成时 clearTimeout */
  timeoutTimer: ReturnType<typeof setTimeout>
  /** agentEndPromise 的 resolve/reject，供 listener 和超时共同收口 */
  resolve: (doc: string) => void
  reject: (err: Error) => void
  /** 源 session 的 client，abort 时调 client.abort() */
  srcClient: IPiEngine
}

private readonly inflight = new Map<string, InflightHandoff>()

{
  "srcSessionId": string,
  "newSessionId": string,
  "sourceLabel": string
}

// 移除字段：doc, reply
// 原因：doc 由 runtime 直接发给新 session pi（newClient.prompt(doc)），不再经前端注入；reply 是用户输入不需回传前端。

{
  type: 'session.handoffAborted',
  payload: { srcSessionId: string }
}

